def remove_odd(l):
    # Check if the input is a tuple
    if isinstance(l, tuple):
        # Filter even numbers and return as a tuple
        return tuple(x for x in l if x % 2 == 0)
    else:
        # Assume it's a list, filter even numbers and return as a list
        return [x for x in l if x % 2 == 0]
